    fn upsert_point(&mut self, op_num: SeqNumberType, point_id: PointIdType, mut vectors: NamedVectors, hw_counter: &HardwareCounterCell) -> OperationResult<bool> {
        debug_assert!(self.is_appendable());
        check_named_vectors(&vectors, &self.segment_config)?;
        vectors.preprocess(|name| self.config().vector_data.get(name).unwrap());
        let stored_internal_point = self.id_tracker.borrow().internal_id(point_id);
        self.handle_point_version_and_failure(op_num, stored_internal_point, |segment| {
            if let Some(existing_internal_id) = stored_internal_point {
                segment.replace_all_vectors(existing_internal_id, op_num, &vectors, hw_counter)?;
                Ok((true, Some(existing_internal_id)))          // EXISTING id -> replace, count unchanged
            } else {
                let new_index = segment.insert_new_vectors(point_id, op_num, &vectors, hw_counter)?;
                Ok((false, Some(new_index)))                    // NEW id -> insert, count +1
            }
        })
    }

